n-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0;flex-basis:50%\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|20\",\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\",\"left\":\"var:preset|spacing|40\",\"right\":\"var:preset|spacing|40\"}}},\"backgroundColor\":\"secondary\",\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"flexWrap\":\"wrap\"}} -->\n<div class=\"wp-block-group has-secondary-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--40);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--40)\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"450px\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:450px\"><!-- wp:paragraph {\"placeholder\":\"Content…\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|background\"}}},\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"textColor\":\"background\",\"fontSize\":\"large\",\"fontFamily\":\"marcellus\"} -->\n<p class=\"has-background-color has-text-color has-link-color has-marcellus-font-family has-large-font-size\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\">Providing high-quality <br>Shisha Charcoal for the best experience</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"left\",\"contentSize\":\"450px\"}} -->\n<div class=\"wp-block-column\" style=\"padding-right:0;padding-left:0\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#ffffff99\"}}},\"color\":{\"text\":\"#ffffff99\"},\"typography\":{\"fontSize\":\"0.85rem\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#ffffff99;font-size:0.85rem\">We are dedicated to producing premium quality charcoal, with a robust production capacity reaching 300 tons per month, ensuring consistent supply and exceptional standards for our customers.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0.5rem\",\"bottom\":\"0.7rem\"}}}} -->\n<div class=\"wp-block-buttons\" style=\"padding-top:0.5rem;padding-bottom:0.7rem\"><!-- wp:button {\"backgroundColor\":\"foreground\",\"className\":\"is-style-fill\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}}},\"fontFamily\":\"marcellus\"} -->\n<div class=\"wp-block-button is-style-fill has-marcellus-font-family\"><a class=\"wp-block-button__link has-foreground-background-color has-background wp-element-button\" style=\"padding-top:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20)\">Find out more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"padding-top:0;padding-right:0;padding-bottom:0;padding-left:0;flex-basis:50%\"><!-- wp:cover {\"url\":\"http://localhost/wordpress/wp-content/up