ound-alt\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"stretch\",\"verticalAlignment\":\"top\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group z-index-99 has-foreground-alt-background-color has-background\" style=\"border-top-left-radius:30px;border-top-right-radius:30px;border-bottom-left-radius:0px;border-bottom-right-radius:0px;margin-top:-40px;margin-bottom:0px;padding-top:0;padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--80)\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"0px\",\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\"}},\"layout\":{\"selfStretch\":\"fill\"},\"border\":{\"bottom\":{\"width\":\"0px\",\"style\":\"none\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"border-bottom-style:none;border-bottom-width:0px;margin-top:var(--wp--preset--spacing--60);margin-bottom:var(--wp--preset--spacing--60);padding-top:0;padding-right:0;padding-bottom:var(--wp--preset--spacing--50);padding-left:0\"><!-- wp:heading {\"textAlign\":\"left\",\"align\":\"wide\",\"style\":{\"typography\":{\"textTransform\":\"none\",\"fontStyle\":\"normal\",\"fontWeight\":\"400\",\"lineHeight\":\"1.1\",\"fontSize\":\"2.5rem\"}},\"textColor\":\"background\"} -->\n<h2 class=\"wp-block-heading alignwide has-text-align-left has-background-color has-text-color\" style=\"font-size:2.5rem;font-style:normal;font-weight:400;line-height:1.1;text-transform:none\">We are an Indonesian Shisha Charcoal Factory constantly striving to produce the highest quality product</h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:separator {\"style\":{\"layout\":{\"selfStretch\":\"fixed\"}}} -->\n<hr class=\"wp-block-separator has-alpha-channel-opacity\"/>\n<!-- /wp:separator -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-columns\" style=\"padding-right:0;padding-left:0\"><!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:paragraph {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|background\"}}}},\"textColor\":\"background\",\"fontFamily\":\"inter\"} -->\n<p class=\"has-background-color has-text-color has-link-color has-inter-font-family\">What you can expect from us:</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"66.66%\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|background\"}}}},\"textColor\":\"background\"} -->\n<div class=\"wp-block-column has-background-color has-text-color has-link-color\" style=\"flex-basis:66.66%\"><!-- wp:paragraph {\"fontFamily\":\"inter\"} -->\n<p class=\"has-inter-font-family\">Robust production capacity reaching 300 tons per month, ensuring consistent supply and exceptional standards for our customers.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"fontFamily\":\"inter\"} -->\n<p class=\"has-inter-font-family\">Made with coconut shell to produce low odour, smooth crack free surface and low ash content quality charcoal reaching up to 600 °C burning temperature.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|50\",\"left\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"}}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\"}} -->\n<div id=\"our_products\" class=\"wp-block-group\" style=\"margin-top:var(--wp--preset--spacing--80);margin-bottom:var(--wp--preset--spacing--80);padding-right:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--50)\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Our Products</h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\",\"top\":\"0\",\"bottom\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":{\"left\":\"var:preset|spacing|80\"}}}} -->\n<div class=\"wp-block-columns\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:column {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-column\" style=\"padding-top:0;padding-bottom:0\"><!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|20\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:var(--wp--preset--spacing--20);padding-top:0;padding-bottom:0\"><!-- wp:image {\"id\":55,\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<figure class=\"wp-block-image size-medium\" style=\"margin-top:0;margin-bottom:var(--wp--preset--spacing--20)\"><img src=\"http://localhost/wordpress/wp-content/uploads/2024/11/charcoal.pro-coconut-charcoal-briquetts-for-shisha-3-pcs-on-heating-768x768-1-300x300.jpg\" alt=\"\" class=\"wp-image-55\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Cube Briquettes</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"typography\":{\"fontSize\":\"0.85rem\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#00000087\"}}},\"color\":{\"text\":\"#00000087\"},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} -->\n<p class=\"has-text-align-left has-text-color has-link-color\" style=\"color:#00000087;font-size:0.85rem\">20, 22, 25, 26, 27, 28, 30, dan 31 mm</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"center\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-bottom:0\"><!-- wp:image {\"id\":56,\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|20\"}}}} -->\n<figure class=\"wp-block-image size-medium\" style=\"margin-bottom:var(--wp--preset--spacing--20)\"><img src=\"http://localhost/wordpress/wp-content/uploads/2024/11/charcoal.pro-coconut-charcoal-briquettes-for-shisha-dome-shape-1024x1024-1-300x300.jpg\" alt=\"\" class=\"wp-image-56\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Finger, Hexa dan Flat</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"0.85rem\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#00000087\"}}},\"color\":{\"text\":\"#00000087\"},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#00000087;font-size:0.85rem\"><a href=\"#\">Reach out for custom requests</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"fontSize\":\"0.8rem\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#00000096\"}}},\"color\":{\"text\":\"#00000096\"}}} -->\n<p class=\"has-text-color has-link-color\" style=\"color:#00000096;font-size:0.8rem\">✖ We do not produce or sell (Raw Material, Pillow Charcoal, Activated Charcoal, BBQ Charcoal)</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:details -->\n<details class=\"wp-block-details\"><summary>FAQ #1</summary><!-- wp:paragraph {\"placeholder\":\"Type / to add a hidden block\"} -->\n<p>Testing paragraphs</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>FAQ #1</summary><!-- wp:paragraph {\"placeholder\":\"Type / to add a hidden block\"} -->\n<p>Testing paragraphs</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>FAQ #1</summary><!-- wp:paragraph {\"placeholder\":\"Type / to add a hidden block\"} -->\n<p>Testing paragraphs</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details -->\n\n<!-- wp:details -->\n<details class=\"wp-block-details\"><summary>FAQ #1</summary><!-- wp:paragraph {\"placeholder\":\"Type / to add a hidden block\"} -->\n<p>Testing paragraphs</p>\n<!-- /wp:paragraph --></details>\n<!-- /wp:details --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"footer\"],\"patternName\":\"extendable/footer-call-to-action\",\"name\":\"Footer, Call to Action\"},\"align\":\"full\",\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|40\",\"padding\":{\"top\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|40\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignfull\" style=\"padding-top:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--40)\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"0px\",\"bottom\":\"1rem\"}}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\" style=\"margin-top:0px;margin-bottom:1rem\">Let\'s Work Together</h2>\n<!-- /wp:heading -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|30\"}}},\"la