ixed\",\"flexSize\":\"330px\"},\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"400\",\"lineHeight\":\"1.4\",\"textTransform\":\"none\",\"textDecoration\":\"none\",\"letterSpacing\":\"0px\"},\"color\":{\"text\":\"#ffffffc4\"},\"elements\":{\"link\":{\"color\":{\"text\":\"#ffffffc4\"}}}},\"fontSize\":\"medium\",\"fontFamily\":\"marcellus\"} -->\n<p class=\"has-text-align-center has-text-color has-link-color has-marcellus-font-family has-medium-font-size\" style=\"color:#ffffffc4;font-style:normal;font-weight:400;letter-spacing:0px;line-height:1.4;text-decoration:none;text-transform:none\">We are CSI (Charcoal Supplier Indonesia), dedicated to providing high-quality shisha charcoal. We deliver premium, eco-friendly charcoal made from 100% natural materials, ensuring a clean and consistent burn.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:image {\"id\":110,\"width\":\"368px\",\"height\":\"auto\",\"sizeSlug\":\"medium\",\"linkDestination\":\"none\",\"className\":\"position-absolute leaves\",\"style\":{\"color\":{\"duotone\":\"unset\"},\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}}} -->\n<figure class=\"wp-block-image size-medium is-resized position-absolute leaves\" style=\"margin-top:0;margin-right:0;margin-bottom:0;margin-left:0\"><img src=\"http://localhost/wordpress/wp-content/uploads/2024/11/Group-1-2-257x300.png\" alt=\"\" class=\"wp-image-110\" style=\"width:368px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"categories\":[\"text\"],\"patternName\":\"extendable/general-three-boxes\",\"name\":\"Our Products\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|80\",\"left\":\"var:preset|spacing|80\",\"top\":\"var:preset|spacing|50\",\"bottom\":\"var:preset|spacing|50\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"gradient\":\"vertical-tertiary-to-background\",\"layout\":{\"inherit\":true,\"type\":\"constrained\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignfull has-vertical-tertiary-to-background-gradient-background has-background\" id=\"our_products\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--80)\"><!-- wp:group {\"metadata\":{\"name\":\"Introduction\"},\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|50\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"margin-bottom:var(--wp--preset--spacing--50)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0px\"}}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"1rem\"}}},\"fontSize\":\"huge\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-huge-font-size\" style=\"margin-bottom:1rem\">Our Products</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"#707070\"}}},\"color\":{\"text\":\"#707070\"}},\"fontSize\":\"small\"} -->\n<p class=\"has-text-align-center has-text-color has-link-color has-small-font-size\" style=\"color:#707070\">We are dedicated to providing the highest quality shisha charcoal products to our discerning customers. We offer two exceptional grades of charcoal to meet your needs:</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:columns {\"align\":\"wide\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"48px\"}}}} -->\n<div class=\"wp-block-columns alignwide\" style=\"margin-top:48px\"><!-- wp:column {\"width\":\"\",\"style\":{\"spacing\":{\"blockGap\":\"0px\",\"padding\":{\"top\":\"var:preset|spacing|30\",\"bottom\":\"var:preset|spacing|30\",\"left\":\"0\",\"right\":\"0\"}},\"border\":{\"radius\":\"10px\"},\"color\":{\"gradient\":\"linear-gradient(135deg,rgb(255,255,255) 0%,rgb(255,234,177) 34%)\"}},\"layout\":{\"type\":\"constrained\",\"wideSize\":\"\",\"contentSize\":\"\"}} -->\n<div class=\"wp-block-column has-background\" style=\"border-radius:10px;background:linear-gradient(135deg,rgb(255,255,255) 0%,rgb(255,234,177) 34%);padding-top:var(--wp--preset--spacing--30);padding-right:0;padding-bottom:var(--wp--preset--spacing--30);padding-left:0\"><!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"right\":\"var:preset|spacing|30\",\"bottom\":\"0\",\"left\":\"var:preset|spacing|30\"},\"margin\":{\"top\":\"0\"},\"blockGap\":\"var:preset|spacing|30\"},\"border\":{\"radius\":\"100px\"},\"dimensions\":{\"minHeight\":\"0px\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"justifyContent\":\"stretch\"}} -->\n<div class=\"wp-block-group\" style=\"border-radius:100px;min-height:0px;margin-top:0;padding-top:0;padding-right:var(--wp--preset--spacing--30);padding-bottom:0;padding-left:var(--wp--preset--spacing--30)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"0\"}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"left\",\"level\":5,\"style\":{\"typography\":{\"fontSize\":\"20px\",\"textTransform\":\"capitalize\",\"fontStyle\":\"normal\",\"fontWeight\":\"700\"}}} -->\n<h5 class=\"wp-block-heading has-text-align-left\" style=\"font-size:20px;font-style:normal;font-weight:700;text-transform:capitalize\">Super Premium</h5>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"left\",\"style\":{\"typography\":{\"fontSize\":\"0.8rem\"}}} -->\n<p class=\"has-text-align-left\" style=\"font-size:0.8rem\">Best quality &amp; price value</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"0\"}},\"lay