imary\",\"textColor\":\"background\",\"fontSize\":\"small\"} -->\n<figure class=\"wp-block-pullquote has-text-align-left has-background-color has-primary-background-color has-text-color has-background has-link-color has-small-font-size\" style=\"min-height:0px;margin-top:0;margin-right:0;margin-bottom:0;margin-left:0;padding-top:var(--wp--preset--spacing--20);padding-right:var(--wp--preset--spacing--30);padding-bottom:var(--wp--preset--spacing--20);padding-left:var(--wp--preset--spacing--30)\"><blockquote><p><strong>Note</strong>: We cannot do customs clearance in your country, but we can recommend a trusted customs broker if you need</p></blockquote></figure>\n<!-- /wp:pullquote --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"50%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:50%\"><!-- wp:columns {\"verticalAlignment\":\"top\",\"style\":{\"spacing\":{\"blockGap\":{\"top\":\"var:preset|spacing|30\",\"left\":\"var:preset|spacing|40\"},\"padding\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-columns are-vertically-aligned-top\" style=\"padding-right:0;padding-left:0\"><!-- wp:column {\"verticalAlignment\":\"top\",\"width\":\"100%\",\"style\":{\"spacing\":{\"padding\":{\"right\":\"0\",\"left\":\"0\"}}}} -->\n<div class=\"wp-block-column is-vertically-aligned-top\" style=\"padding-right:0;padding-left:0;flex-basis:100%\"><!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"right\":\"0\",\"left\":\"0\"}}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"400px\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:0;padding-right:0;padding-left:0\"><!-- wp:table {\"className\":\"is-style-regular\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|background\"}}},\"border\":{\"width\":\"1px\"},\"typography\":{\"fontSize\":\"1rem\"}},\"backgroundColor\":\"pr